DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_verificar_stock_bajo` AFTER UPDATE ON `materiaprima` FOR EACH ROW BEGIN
    IF NEW.StockActual <= NEW.StockMinimo AND NEW.Activo = 1 THEN
        IF NOT EXISTS (SELECT 1 FROM alertasistema 
                       WHERE ReferenciaId = NEW.IdMateriaPrima 
                       AND TipoAlerta = 'STOCK_BAJO' 
                       AND Leida = 0) THEN
            
            INSERT INTO alertasistema (TipoAlerta, ReferenciaId, Mensaje, IdUsuarioDestino)
            VALUES (
                'STOCK_BAJO', 
                NEW.IdMateriaPrima, 
                CONCAT('El material ', NEW.Nombre, ' ha alcanzado un nivel crÃ­tico: ', NEW.StockActual),
                NULL 
            );
        END IF;
    END IF;
END */;;
