CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Clientes_Activar`(IN p_IdCliente INT)
BEGIN
    UPDATE Persona p
    INNER JOIN Cliente c ON c.IdPersona = p.IdPersona
    SET p.Activo = 1
    WHERE c.IdCliente = p_IdCliente;
END ;;
