CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Clientes_Listar`()
BEGIN
    SELECT
        c.IdCliente,
        c.PermiteCompraOnline,
        p.Nombre,
        p.Apellidos,
        p.CorreoElectronico,
        p.Telefono,
        p.Foto,
        p.Activo
    FROM Cliente c
    INNER JOIN Persona p ON p.IdPersona = c.IdPersona
    ORDER BY p.Activo DESC, p.Apellidos ASC;
END ;;
DELIMITER ;
