DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Clientes_VerPerfil`(IN p_IdCliente INT)
BEGIN
    SELECT
        c.IdCliente,
        c.PermiteCompraOnline,
        p.Nombre,
        p.Apellidos,
        p.CorreoElectronico,
        p.Telefono,
        p.Direccion,
        p.Foto,
        u.Identificador
    FROM Cliente c
    INNER JOIN Persona p ON p.IdPersona = c.IdPersona
    LEFT JOIN Usuario u ON u.IdPersona = c.IdPersona
    WHERE c.IdCliente = p_IdCliente
    LIMIT 1;
END ;;
DELIMITER ;
