CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_AlertasStockMateriaPrima`()
BEGIN
    SELECT
        mp.IdMateriaPrima,
        mp.Nombre,
        mp.StockActual,
        mp.StockMinimo,
        um.Abreviatura
    FROM MateriaPrima mp
    LEFT JOIN UnidadMedida um ON um.IdUnidadMedida = mp.IdUnidadMedida
    WHERE mp.Activo = 1
      AND mp.StockActual <= mp.StockMinimo
    ORDER BY (mp.StockMinimo - mp.StockActual) DESC;
END ;;
DELIMITER ;
