CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_AlertasStockProducto`()
BEGIN
    SELECT
        IdProductoTerminado,
        Nombre,
        StockActual,
        StockMinimo
    FROM ProductoTerminado
    WHERE Activo = 1
      AND StockActual <= StockMinimo
    ORDER BY (StockMinimo - StockActual) DESC;
END ;;
