/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_Defectos`()
BEGIN
    SELECT
        DATE(p.FechaFin) AS Etiqueta,
        SUM(pd.CantidadDefectuosa)   AS TotalDefectos,
        SUM(p.CantidadFabricada)     AS TotalProduccion,
        ROUND(
            (SUM(pd.CantidadDefectuosa) / NULLIF(SUM(p.CantidadFabricada), 0)) * 100,
            2
        ) AS PorcentajeDefectos,

        SUM(CASE
            WHEN LOWER(pd.Descripcion) REGEXP
                 'fisura|fractura|roto|crack|quiebre|falla|severo|cr.tico|inutilizable'
            THEN pd.CantidadDefectuosa ELSE 0
        END) AS Alto,

        SUM(CASE
            WHEN LOWER(pd.Descripcion) NOT REGEXP
                 'fisura|fractura|roto|crack|quiebre|falla|severo|cr.tico|inutilizable'
             AND LOWER(pd.Descripcion) REGEXP
                 'color|medida|tolerancia|inconsistente|deformado|manchado|incompleto'
            THEN pd.CantidadDefectuosa ELSE 0
        END) AS Medio,

        SUM(CASE
            WHEN (pd.Descripcion IS NULL OR pd.Descripcion = '')
              OR (
                LOWER(pd.Descripcion) NOT REGEXP
                    'fisura|fractura|roto|crack|quiebre|falla|severo|cr.tico|inutilizable'
                AND LOWER(pd.Descripcion) NOT REGEXP
                    'color|medida|tolerancia|inconsistente|deformado|manchado|incompleto'
              )
            THEN pd.CantidadDefectuosa ELSE 0
        END) AS Bajo

    FROM Produccion p
    LEFT JOIN ProduccionDefectuosa pd ON pd.IdProduccion = p.IdProduccion
    WHERE p.FechaFin >= CURDATE() - INTERVAL 6 DAY
      AND p.Estado = 'Completada'
    GROUP BY DATE(p.FechaFin)
    ORDER BY DATE(p.FechaFin);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
