/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_GraficaAnio`()
BEGIN
    SELECT
        DATE_FORMAT(v.FechaVenta, '%Y-%m')                       AS Mes,
        COALESCE(SUM(vd.Cantidad * vd.PrecioUnitario), 0)        AS Ventas,
        COALESCE(SUM(
            vd.Cantidad * vd.PrecioUnitario
            - vd.Cantidad * (
                SELECT COALESCE(SUM(
                    CASE
                        WHEN um.Abreviatura IN ('g', 'ml')
                            THEN (rd.CantidadRequerida + rd.Merma) * (mp.PrecioUnitario / 1000)
                        ELSE
                            (rd.CantidadRequerida + rd.Merma) * mp.PrecioUnitario
                    END
                ), 0)
                FROM Receta r
                INNER JOIN RecetaDetalle rd ON rd.IdProductoTerminado = r.IdProductoTerminado
                INNER JOIN MateriaPrima mp  ON mp.IdMateriaPrima       = rd.IdMateriaPrima
                LEFT  JOIN UnidadMedida um  ON um.IdUnidadMedida       = mp.IdUnidadMedida
                WHERE r.IdProductoTerminado = vd.IdProductoTerminado
                  AND r.Activa = 1
            )
        ), 0)                                                     AS Utilidad
    FROM Venta v
    INNER JOIN VentaDetalle vd ON vd.IdVenta = v.IdVenta
    WHERE v.FechaVenta >= CURDATE() - INTERVAL 12 MONTH
    GROUP BY DATE_FORMAT(v.FechaVenta, '%Y-%m')
    ORDER BY DATE_FORMAT(v.FechaVenta, '%Y-%m') ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
