DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_GraficaMes`()
BEGIN
    SELECT
        WEEK(v.FechaVenta, 1)                                    AS Semana,
        MIN(DATE(v.FechaVenta))                                  AS FechaInicioSemana,
        COALESCE(SUM(vd.Cantidad * vd.PrecioUnitario), 0)        AS Ventas,
        COALESCE(SUM(
            vd.Cantidad * vd.PrecioUnitario
            - vd.Cantidad * (
                SELECT COALESCE(SUM(
                    CASE
                        WHEN um.Abreviatura IN ('g', 'ml')
                            THEN (rd.CantidadRequerida + rd.Merma) * (mp.PrecioUnitario / 1000)
                        ELSE
                            (rd.CantidadRequerida + rd.Merma) * mp.PrecioUnitario
                    END
                ), 0)
                FROM Receta r
                INNER JOIN RecetaDetalle rd ON rd.IdProductoTerminado = r.IdProductoTerminado
                INNER JOIN MateriaPrima mp  ON mp.IdMateriaPrima       = rd.IdMateriaPrima
                LEFT  JOIN UnidadMedida um  ON um.IdUnidadMedida       = mp.IdUnidadMedida
                WHERE r.IdProductoTerminado = vd.IdProductoTerminado
                  AND r.Activa = 1
            )
        ), 0)                                                     AS Utilidad
    FROM Venta v
    INNER JOIN VentaDetalle vd ON vd.IdVenta = v.IdVenta
    WHERE v.FechaVenta >= CURDATE() - INTERVAL 29 DAY
    GROUP BY WEEK(v.FechaVenta, 1)
    ORDER BY WEEK(v.FechaVenta, 1) ASC;
END ;;
DELIMITER ;
