CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_KPIsHoy`()
BEGIN
    SELECT
        COALESCE(SUM(vd.Cantidad * vd.PrecioUnitario), 0) AS VentaTotal,
        COALESCE(SUM(vd.Cantidad * vd.PrecioUnitario) * 0.3, 0) AS UtilidadTotal
    FROM Venta v
    JOIN VentaDetalle vd ON vd.IdVenta = v.IdVenta
    WHERE DATE(v.FechaVenta) = CURDATE();
END ;;
