CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Dashboard_TopGananciaSemanaActual`()
BEGIN
    SELECT
        pt.IdProductoTerminado,
        pt.Nombre                            AS NombreProducto,
        SUM(vd.Cantidad)                     AS TotalUnidades,
        pt.PrecioVenta,
        SUM(vd.Cantidad * vd.PrecioUnitario) AS TotalGanancia
    FROM Venta v
    INNER JOIN VentaDetalle vd      ON vd.IdVenta             = v.IdVenta
    INNER JOIN ProductoTerminado pt ON pt.IdProductoTerminado = vd.IdProductoTerminado
    WHERE YEARWEEK(v.FechaVenta, 1) = YEARWEEK(CURDATE(), 1)
    GROUP BY pt.IdProductoTerminado, pt.Nombre, pt.PrecioVenta
    ORDER BY TotalGanancia DESC
    LIMIT 1;
END ;;
