CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Empleados_Listar`()
BEGIN
    SELECT
        e.IdEmpleado,
        e.Puesto,
        e.Salario,
        e.Activo,
        p.Nombre,
        p.Apellidos,
        p.CorreoElectronico,
        p.Telefono,
        p.Foto,
        u.Identificador,
        r.Nombre AS NombreRol
    FROM Empleado e
    INNER JOIN Persona p ON p.IdPersona = e.IdPersona
    LEFT JOIN Usuario u ON u.IdPersona = e.IdPersona
    LEFT JOIN Rol r ON r.IdRol = u.IdRol
    ORDER BY e.Activo DESC, p.Apellidos ASC;
END ;;
DELIMITER ;
