CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Produccion_Cancelar`(
    IN p_id_produccion INT,
    IN p_id_usuario    INT
)
BEGIN
    DECLARE v_id_producto       INT;
    DECLARE v_cantidad_planeada INT;
    DECLARE v_id_mp             INT;
    DECLARE v_cant_req          DECIMAL(18,2);
    DECLARE v_merma             DECIMAL(18,2);
    DECLARE v_precio_mp         DECIMAL(18,2);
    DECLARE v_necesario         DECIMAL(18,2);
    DECLARE done                INT DEFAULT 0;

    DECLARE cur_mp CURSOR FOR
        SELECT rd.IdMateriaPrima,
               rd.CantidadRequerida,
               rd.Merma,
               mp.PrecioUnitario
          FROM RecetaDetalle rd
         INNER JOIN MateriaPrima mp ON mp.IdMateriaPrima = rd.IdMateriaPrima
         WHERE rd.IdProductoTerminado = v_id_producto;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    SELECT IdProductoTerminado, CantidadPlaneada
      INTO v_id_producto, v_cantidad_planeada
      FROM Produccion
     WHERE IdProduccion = p_id_produccion
     LIMIT 1;

    
    OPEN cur_mp;
    revert_loop: LOOP
        FETCH cur_mp INTO v_id_mp, v_cant_req, v_merma, v_precio_mp;
        IF done THEN LEAVE revert_loop; END IF;

        SET v_necesario = (v_cant_req + v_merma) * v_cantidad_planeada;

        UPDATE MateriaPrima
           SET StockActual = StockActual + v_necesario
         WHERE IdMateriaPrima = v_id_mp;

        INSERT INTO MovimientoMateriaPrima
            (IdMateriaPrima, TipoMovimiento, Cantidad, CostoUnitario, FechaMovimiento, Motivo, IdUsuario)
        VALUES
            (v_id_mp, 'Entrada', v_necesario, v_precio_mp, NOW(),
             CONCAT('CancelaciÃ³n ProducciÃ³n #', p_id_produccion), p_id_usuario);
    END LOOP;
    CLOSE cur_mp;

    
    UPDATE Produccion
       SET Estado   = 'Cancelada',
           FechaFin = NOW()
     WHERE IdProduccion = p_id_produccion;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
