CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Produccion_CompletadasHoy`()
BEGIN
    SELECT
        p.IdProduccion,
        p.IdSolicitudProduccion,
        p.IdProductoTerminado,
        p.CantidadPlaneada,
        p.CantidadFabricada,
        p.CantidadDefectuosa,
        p.FechaInicio,
        p.FechaFin,
        p.Estado,
        p.IdUsuarioRegistro,
        pt.Nombre     AS NombreProducto,
        per.Nombre    AS NombreRegistro,
        per.Apellidos AS ApellidosRegistro
    FROM Produccion p
    INNER JOIN ProductoTerminado pt  ON pt.IdProductoTerminado = p.IdProductoTerminado
    INNER JOIN Usuario u             ON u.IdUsuario            = p.IdUsuarioRegistro
    INNER JOIN Persona per           ON per.IdPersona          = u.IdPersona
    WHERE p.Estado = 'Completada'
      AND DATE(p.FechaFin) = CURDATE()
    ORDER BY p.FechaFin DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
