CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Produccion_Finalizar`(
    IN p_id_produccion        INT,
    IN p_cantidad_buenas      INT,
    IN p_cantidad_defectuosas INT,
    IN p_id_usuario           INT
)
BEGIN
    DECLARE v_id_producto   INT;
    DECLARE v_costo         DECIMAL(18,2) DEFAULT 0;

    SELECT IdProductoTerminado INTO v_id_producto
      FROM Produccion
     WHERE IdProduccion = p_id_produccion
     LIMIT 1;

    SELECT COALESCE(SUM((rd.CantidadRequerida + rd.Merma) * mp.PrecioUnitario), 0)
      INTO v_costo
      FROM RecetaDetalle rd
      INNER JOIN MateriaPrima mp ON mp.IdMateriaPrima = rd.IdMateriaPrima
     WHERE rd.IdProductoTerminado = v_id_producto;

    UPDATE Produccion
       SET CantidadFabricada   = p_cantidad_buenas,
           CantidadDefectuosa  = p_cantidad_defectuosas,
           Estado              = 'Completada',
           FechaFin            = NOW()
     WHERE IdProduccion = p_id_produccion;

    UPDATE ProductoTerminado
       SET StockActual = StockActual + p_cantidad_buenas
     WHERE IdProductoTerminado = v_id_producto;

    INSERT INTO MovimientoProductoTerminado
        (IdProductoTerminado, TipoMovimiento, Cantidad, FechaMovimiento, Motivo, CostoUnitario, IdUsuario)
    VALUES
        (v_id_producto, 'Entrada', p_cantidad_buenas, NOW(),
         CONCAT('ProducciÃ³n #', p_id_produccion), v_costo, p_id_usuario);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
