CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Produccion_Iniciar`(
    IN  p_id_produccion INT,
    IN  p_id_usuario    INT,
    OUT p_ok            TINYINT,
    OUT p_mensaje       VARCHAR(255)
)
sp_body: BEGIN
    DECLARE v_estado            VARCHAR(20);
    DECLARE v_id_producto       INT;
    DECLARE v_cantidad_planeada INT;
    DECLARE v_receta_activa     INT DEFAULT 0;
    DECLARE v_id_mp             INT;
    DECLARE v_cant_req          DECIMAL(18,2);
    DECLARE v_merma             DECIMAL(18,2);
    DECLARE v_stock_actual      DECIMAL(18,2);
    DECLARE v_necesario         DECIMAL(18,2);
    DECLARE v_nombre_mp         VARCHAR(150);
    DECLARE v_precio_mp         DECIMAL(18,2);
    DECLARE done                INT DEFAULT 0;

    DECLARE cur_mp CURSOR FOR
        SELECT rd.IdMateriaPrima,
               rd.CantidadRequerida,
               rd.Merma,
               mp.StockActual,
               mp.Nombre,
               mp.PrecioUnitario
        FROM RecetaDetalle rd
        INNER JOIN MateriaPrima mp 
            ON mp.IdMateriaPrima = rd.IdMateriaPrima
        WHERE rd.IdProductoTerminado = v_id_producto;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    SET p_ok = 0;
    SET p_mensaje = '';

    SELECT Estado, IdProductoTerminado, CantidadPlaneada
      INTO v_estado, v_id_producto, v_cantidad_planeada
      FROM Produccion
     WHERE IdProduccion = p_id_produccion
     LIMIT 1;

    IF v_estado IS NULL THEN
        SET p_mensaje = 'ProducciÃ³n no encontrada.';
        LEAVE sp_body;
    END IF;

    IF v_estado <> 'Aprobada' THEN
        SET p_mensaje = CONCAT(
            'Estado invÃ¡lido: ', v_estado,
            '. Solo se puede iniciar una producciÃ³n Aprobada.'
        );
        LEAVE sp_body;
    END IF;

    SELECT COUNT(*)
      INTO v_receta_activa
      FROM Receta
     WHERE IdProductoTerminado = v_id_producto
       AND Activa = 1
       AND Aprobada = 1;

    IF v_receta_activa = 0 THEN
        SET p_mensaje = 'El producto no tiene receta activa y aprobada.';
        LEAVE sp_body;
    END IF;

    OPEN cur_mp;

    check_loop: LOOP
        FETCH cur_mp INTO v_id_mp, v_cant_req, v_merma, v_stock_actual, v_nombre_mp, v_precio_mp;

        IF done = 1 THEN
            LEAVE check_loop;
        END IF;

        SET v_necesario = (v_cant_req + v_merma) * v_cantidad_planeada;

        IF v_stock_actual < v_necesario THEN
            CLOSE cur_mp;
            SET p_mensaje = CONCAT(
                'Stock insuficiente de "', v_nombre_mp,
                '": necesario ', v_necesario,
                ', disponible ', v_stock_actual, '.'
            );
            LEAVE sp_body;
        END IF;
    END LOOP;

    CLOSE cur_mp;

    SET done = 0;
    OPEN cur_mp;

    descuento_loop: LOOP
        FETCH cur_mp INTO v_id_mp, v_cant_req, v_merma, v_stock_actual, v_nombre_mp, v_precio_mp;

        IF done = 1 THEN
            LEAVE descuento_loop;
        END IF;

        SET v_necesario = (v_cant_req + v_merma) * v_cantidad_planeada;

        UPDATE MateriaPrima
           SET StockActual = StockActual - v_necesario
         WHERE IdMateriaPrima = v_id_mp;

        INSERT INTO MovimientoMateriaPrima
            (IdMateriaPrima, TipoMovimiento, Cantidad, CostoUnitario, FechaMovimiento, Motivo, IdUsuario)
        VALUES
            (
                v_id_mp,
                'Salida',
                v_necesario,
                v_precio_mp,
                NOW(),
                CONCAT('ProducciÃ³n #', p_id_produccion),
                p_id_usuario
            );
    END LOOP;

    CLOSE cur_mp;

    UPDATE Produccion
       SET Estado = 'En proceso',
           FechaInicio = NOW()
     WHERE IdProduccion = p_id_produccion;

    SET p_ok = 1;
    SET p_mensaje = 'ProducciÃ³n iniciada correctamente.';

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
