CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Produccion_KPIsHoy`()
BEGIN
    SELECT
        COUNT(CASE WHEN Estado = 'Aprobada'    THEN 1 END) AS Aprobadas,
        COUNT(CASE WHEN Estado = 'En proceso'  THEN 1 END) AS EnProceso,
        COUNT(CASE WHEN Estado = 'Completada'
                    AND DATE(FechaFin) = CURDATE() THEN 1 END) AS Completadas,
        COALESCE(SUM(CASE WHEN Estado = 'Completada'
                           AND DATE(FechaFin) = CURDATE()
                          THEN CantidadDefectuosa END), 0) AS TotalDefectuosas
    FROM Produccion;
END ;;
DELIMITER ;
