CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Produccion_Ver`(
    IN p_id INT
)
BEGIN
    SELECT
        p.IdProduccion,
        p.IdSolicitudProduccion,
        p.IdProductoTerminado,
        p.CantidadPlaneada,
        p.CantidadFabricada,
        p.CantidadDefectuosa,
        p.FechaInicio,
        p.FechaFin,
        p.Estado,
        p.IdUsuarioRegistro,
        pt.Nombre        AS NombreProducto,
        pt.Descripcion   AS DescripcionProducto,
        per.Nombre       AS NombreRegistro,
        per.Apellidos    AS ApellidosRegistro
    FROM Produccion p
    INNER JOIN ProductoTerminado pt  ON pt.IdProductoTerminado = p.IdProductoTerminado
    INNER JOIN Usuario u             ON u.IdUsuario            = p.IdUsuarioRegistro
    INNER JOIN Persona per           ON per.IdPersona          = u.IdPersona
    WHERE p.IdProduccion = p_id
    LIMIT 1;
END ;;
DELIMITER ;
