CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_RegistrarCompraMateriaPrima`(
    IN p_IdProveedor INT,
    IN p_Observaciones TEXT,
    IN p_IdUsuario INT,
    IN p_IdMateriaPrima INT,
    IN p_Cantidad DECIMAL(18,2),
    IN p_CostoUnitario DECIMAL(18,2)
)
BEGIN
    DECLARE v_IdCompra INT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
    END;

    START TRANSACTION;
        INSERT INTO compramateriaprima (FechaCompra, IdProveedor, Observaciones, IdUsuarioRegistro)
        VALUES (NOW(), p_IdProveedor, p_Observaciones, p_IdUsuario);
        
        SET v_IdCompra = LAST_INSERT_ID();

        INSERT INTO compramateriaprimadetalle (IdCompraMateriaPrima, IdMateriaPrima, Cantidad, CostoUnitario)
        VALUES (v_IdCompra, p_IdMateriaPrima, p_Cantidad, p_CostoUnitario);

        UPDATE materiaprima 
        SET Existencias = Existencias + p_Cantidad
        WHERE IdMateriaPrima = p_IdMateriaPrima;

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
