CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_movimiento_mp`(
    IN p_id_mp INT,
    IN p_tipo VARCHAR(10),
    IN p_cantidad DECIMAL(10,2),
    IN p_costo DECIMAL(10,2),
    IN p_motivo TEXT,
    IN p_usuario INT
)
BEGIN
    DECLARE v_stock_actual DECIMAL(10,2);
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;
        SELECT StockActual INTO v_stock_actual FROM MateriaPrima WHERE IdMateriaPrima = p_id_mp;

        IF p_tipo = 'SALIDA' AND v_stock_actual < p_cantidad THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: Stock insuficiente para realizar la salida.';
        END IF;

        INSERT INTO MovimientoMateriaPrima (IdMateriaPrima, TipoMovimiento, Cantidad, CostoUnitario, Motivo, IdUsuario, FechaMovimiento)
        VALUES (p_id_mp, p_tipo, p_cantidad, p_costo, p_motivo, p_usuario, NOW());

        IF p_tipo = 'ENTRADA' THEN
            UPDATE MateriaPrima SET StockActual = StockActual + p_cantidad WHERE IdMateriaPrima = p_id_mp;
        ELSE
            UPDATE MateriaPrima SET StockActual = StockActual - p_cantidad WHERE IdMateriaPrima = p_id_mp;
        END IF;
    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
