CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_SolicitudProduccion_Crear`(
    IN  p_IdProductoTerminado INT,
    IN  p_CantidadSolicitada  INT,
    IN  p_Motivo              VARCHAR(255),
    IN  p_IdUsuarioSolicita   INT
)
BEGIN
    INSERT INTO SolicitudProduccion (
        IdProductoTerminado,
        CantidadSolicitada,
        Motivo,
        Estado,
        FechaSolicitud,
        IdUsuarioSolicita
    ) VALUES (
        p_IdProductoTerminado,
        p_CantidadSolicitada,
        p_Motivo,
        'PENDIENTE',
        NOW(),
        p_IdUsuarioSolicita
    );
END ;;
DELIMITER ;
